/* Hasaad Platform — Supplier Q&A inbox. Supplier account must be linked to its catalog vendorId. */
import { useMemo, useState } from "react";
import { AlertTriangle, CheckCircle2, MessageCircleQuestion, Package, Send } from "lucide-react";
import { toast } from "sonner";
import VendorSidebar from "@/components/vendor/VendorSidebar";
import VendorHeader from "@/components/vendor/VendorHeader";
import { trpc } from "@/lib/trpc";
import { getPendingQuestionPriority } from "@/lib/questionResponsePriority";

export default function VendorProductQuestions() {
  const utils = trpc.useUtils();
  const questionsQuery = trpc.productQuestions.vendorList.useQuery();
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const answerMutation = trpc.productQuestions.answer.useMutation({ onSuccess: () => { utils.productQuestions.vendorList.invalidate(); toast.success("تم نشر ردك في صفحة المنتج"); }, onError: () => toast.error("تعذر نشر الرد") });
  const pending = useMemo(() => (questionsQuery.data ?? []).filter((item) => item.status === "pending"), [questionsQuery.data]);
  return <div className="flex h-screen overflow-hidden bg-[#F5F1E8]" dir="rtl"><VendorSidebar vendorType="supplier" /><div className="flex min-w-0 flex-1 flex-col overflow-hidden"><VendorHeader vendorType="supplier" pageTitle="أسئلة المنتجات" pageSubtitle="أجب عن استفسارات المزارعين قبل الشراء" /><main className="flex-1 overflow-y-auto p-5 sm:p-6"><div className="mx-auto max-w-5xl"><div className="mb-5 flex items-center gap-3 rounded-2xl bg-[#EAF5E7] p-4 text-[#1F6B45]"><MessageCircleQuestion className="h-6 w-6" /><div><p className="font-black">{pending.length.toLocaleString("ar-SA")} سؤال بانتظار ردك</p><p className="mt-1 text-xs">الأسئلة التي تجاوزت 24 ساعة مميزة بشارة أولوية.</p></div></div>{questionsQuery.isLoading ? <div className="space-y-3">{Array.from({ length: 3 }).map((_, index) => <div key={index} className="h-40 animate-pulse rounded-2xl bg-white" />)}</div> : questionsQuery.isError ? <div className="rounded-2xl border border-amber-200 bg-amber-50 p-8 text-center text-sm text-amber-800">حساب المورد يحتاج ربطاً بملف المورد المعتمد قبل عرض الأسئلة.</div> : (questionsQuery.data ?? []).length === 0 ? <div className="rounded-2xl border border-dashed border-[#D6E3D2] bg-white p-12 text-center"><Package className="mx-auto h-9 w-9 text-[#9AABA0]" /><p className="mt-3 font-black text-[#304B3A]">لا توجد أسئلة على منتجاتك حالياً</p></div> : <div className="space-y-4">{questionsQuery.data?.map((item) => { const priority = item.status === "pending" ? getPendingQuestionPriority(item.createdAt) : null; return <article key={item.id} className={`rounded-2xl border bg-white p-5 shadow-sm ${priority?.isOverdue ? "border-red-200 ring-1 ring-red-100" : "border-[#DCE7D9]"}`}><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold text-[#5D896E]">{item.vendorName}</p><h2 className="mt-1 text-base font-black text-[#223D2D]">{item.question}</h2><p className="mt-2 text-xs text-[#75847B]">سؤال من {item.askerName} · {new Date(item.createdAt).toLocaleDateString("ar-SA")}</p></div><div className="flex shrink-0 flex-col items-end gap-2">{priority?.isOverdue && <span title={`معلّق منذ ${priority.elapsedHours} ساعة`} className="inline-flex items-center gap-1 rounded-full bg-red-100 px-2.5 py-1 text-xs font-bold text-red-700"><AlertTriangle className="h-3.5 w-3.5" />أولوية: منذ {priority.elapsedHours} ساعة</span>}{item.status === "answered" && <span className="inline-flex items-center gap-1 rounded-full bg-[#EAF5E7] px-2.5 py-1 text-xs font-bold text-[#1F6B45]"><CheckCircle2 className="h-3.5 w-3.5" />تمت الإجابة</span>}</div></div>{item.status === "answered" ? <div className="mt-4 rounded-xl bg-[#F7FAF5] p-3 text-sm leading-7 text-[#526359]"><span className="mb-1 block text-xs font-bold text-[#5D896E]">ردك المنشور</span>{item.answer}</div> : <div className="mt-4"><textarea value={drafts[item.id] ?? ""} onChange={(event) => setDrafts((previous) => ({ ...previous, [item.id]: event.target.value }))} className="min-h-24 w-full resize-none rounded-xl border border-[#D7E4D4] px-3 py-2.5 text-sm outline-none focus:border-[#2C7A4A]" placeholder="اكتب إجابة واضحة ومفيدة للمزارع..." /><div className="mt-3 flex justify-end"><button disabled={answerMutation.isPending || !(drafts[item.id] ?? "").trim()} onClick={() => answerMutation.mutate({ id: item.id, answer: drafts[item.id].trim() })} className="inline-flex items-center gap-2 rounded-xl bg-[#2E7D32] px-4 py-2.5 text-sm font-black text-white disabled:opacity-50"><Send className="h-4 w-4" />نشر الإجابة</button></div></div>}</article>; })}</div>}</div></main></div></div>;
}
